from lib import *
S = SS('g58')
steps = [
    step("4 个 goroutine 各 5 次抢同一把锁(每次持锁 5 ms),trace 只有 5592 字节。go tool trace -pprof=sync 的结果(总计 537.23ms):sync.(*Mutex).Lock 314.33ms(58.51%),调用者 main.holdLock;sync.(*WaitGroup).Wait 122.83ms(22.86%);runtime.chanrecv1 100.08ms(18.63%),它来自运行时自己的 traceStartReadCPU(运行时内部的 goroutine,不是用户代码)。", t=tl(S(1)), done=lidx(S(1), 'sync.(*Mutex).Lock', 'main.holdLock'), mark=lidx(S(1), 'sync.(*WaitGroup).Wait', 'runtime.chanrecv1', 'traceStartReadCPU'), b=bars([['Mutex.Lock 上的等待 (ms)', 314.33, '314.33'], ['WaitGroup.Wait', 122.83, '122.83'], ['运行时内部 chanrecv1', 100.08, '100.08']], 314.33, done=[0], mark=[1, 2]), kv=KV([['Lock', '314.33 ms,归到 main.holdLock'], ['混入的内部项', 'chanrecv1 100.08 ms 来自运行时自己'], ['trace 大小', '5592 字节']], ['混入的内部项'])),
    step("GOMAXPROCS=1,20 个各自空转 20 ms 的 goroutine 同时就绪。程序自己量到的:从创建到第一次运行的等待之和 3559 ms;创建到结束的总时间之和 5090 ms,减去各自 20 ms 的空转 = 4690 ms 排队时间。go tool trace -pprof=sched 给出的总量(1906.32ms)只有它的一部分:time.Now 1155.78ms(60.63%)、runtime.wakeNetPoller 375.28ms(19.69%)。同一程序另几次运行的总量是 804.83ms、1353.41ms。为什么 trace 的总量比直接量的小、还不稳定,我没有查清。", t=tl(S(2)), done=lidx(S(2), '程序自己量的'), mark=lidx(S(2), 'time.Now', 'wakeNetPoller', 'Showing nodes accounting'), b=bars([['程序自己量的排队时间 (ms)', 4690, '4690'], ['sched profile 总量', 1906, '1906'], ['另一次运行', 1353, '1353'], ['再一次', 805, '805']], 4690, done=[0], mark=[1, 2, 3]), kv=KV([['直接测量', '排队约 4690 ms'], ['sched profile', '1906 / 1353 / 805 ms(三次运行)'], ['结论', '别把 -pprof=sched 的总量当精确值'], ['未查', '总量偏小的原因']], ['结论'])),
    step("用户标注:trace.NewTask 与 trace.WithRegion(三个各 time.Sleep(10ms) 的步骤)。go tool trace -d=parsed 把它们列成事件:TaskBegin(Type=\"请求\")、每个区域的 RegionBegin/RegionEnd(Task=1)、Log(Category=\"category\", Message=\"done\")。按事件的 Time 相减:解析 12.03 ms、查询 12.03 ms、渲染 12.01 ms(代码里睡 10 ms,实际睡眠就超出约 2 ms,与之前 Sleep 的测量一致)。", t=tl(S(3)), done=lidx(S(3), 'TaskBegin', 'Log Time'), mark=lidx(S(3), '区域 解析', '区域 查询', '区域 渲染'), b=bars([['解析 (ms)', 12.03, '12.03'], ['查询', 12.03, '12.03'], ['渲染', 12.01, '12.01']], 12.03, mark=[0, 1, 2]), kv=KV([['事件类型', 'TaskBegin / RegionBegin / RegionEnd / Log'], ['区域时长', '12.03 / 12.03 / 12.01 ms'], ['代码里的睡眠', '10 ms']], ['区域时长'])),
    step("开着 trace 的代价:200 个 goroutine 各分配 400 次并 Gosched,每种各跑 5 次。不开 trace:最小 0.040 s / 中位 0.041 s / 最大 0.042 s;开 trace:0.048 / 0.050 / 0.050 s,约慢 22%;trace 文件 0.9 MB(0.050 s 约 0.9 MB,即每秒约 18 MB)。", t=tl(S(4)), done=lidx(S(4), 'plain'), mark=lidx(S(4), 'traced'), b=bars([['plain 中位 (ms)', 41, '41'], ['traced 中位', 50, '50']], 50, done=[0], mark=[1]), kv=KV([['不开', '中位 0.041 s'], ['开', '中位 0.050 s,约 +22%'], ['trace 大小', '0.9 MB / 0.05 s']], ['开'])),
    step("帮助与文档原文:execution trace 捕获 goroutine 创建/阻塞/唤醒、系统调用进入/退出/阻塞、GC 相关事件、堆大小变化、P 的启停等,大多数事件带纳秒时间戳和调用栈,用 go tool trace 解读。go tool trace -pprof=TYPE 支持四种:net(网络阻塞)、sync(同步阻塞)、syscall(系统调用阻塞)、sched(调度延迟)。", t=tl(S(5)), done=lidx(S(5), 'goroutine', 'nanosecond-precision'), mark=lidx(S(5), '- net:', '- sync:', '- syscall:', '- sched:'), kv=KV([['事件', 'goroutine、系统调用、GC、堆、P 启停'], ['-pprof 类型', 'net / sync / syscall / sched'], ['时间精度', '纳秒级时间戳 + 栈']], ['-pprof 类型'])),
]
A = mkartg('g58', 58, 'Go,执行追踪,go tool trace,trace,调度延迟,真实验证,动画演示',
    '在 Go 1.27.1 里实测执行追踪:go tool trace -pprof=sync 把 4 个 goroutine 争锁的等待(Mutex.Lock 314.33 ms)归到 main.holdLock;-pprof=sched 的调度延迟总量(804–1906 ms)明显低于程序直接量到的排队时间 4690 ms;用户标注的区域时长 12.03/12.03/12.01 ms;开 trace 让一个分配密集的程序慢约 22%、每秒约 18 MB。',
    'CPU profile 看不到 goroutine 在等什么。执行追踪记录每个 goroutine 的阻塞、唤醒、调度,可以回答“它在哪里等了多久”。这篇不用网页界面,用命令行把 trace 导成 pprof 和事件文本,并用程序自己的计时校验 trace 给出的数字。',
    [('314.33 ms', '4 个 goroutine 争锁时,trace 的 sync 阻塞 profile 归到 Mutex.Lock 的等待'), ('4690 vs 1906 ms', '20 个 goroutine 排队:程序自己量到的排队时间对 sched profile 的总量(单次运行)'), ('+22%', '开着 trace 时,分配密集的小程序耗时增加')],
    [('sync 阻塞 profile', '<p><code>go tool trace -pprof=sync</code> 把 goroutine 阻塞在同步原语上的时间按调用栈汇总。4 个 goroutine 争锁的例子里,<code>Mutex.Lock</code> 记了 314.33 ms、归到 <code>main.holdLock</code>;另外混进了运行时自己的 goroutine 的 100 ms(<code>traceStartReadCPU</code>),读这类结果要认得哪些是运行时内部的项。</p>'),
     ('sched profile 要小心', '<p>20 个 goroutine 在一个 P 上排队,程序自己量出来的排队时间是 4690 ms,而 <code>-pprof=sched</code> 的总量只有 1906 ms(另外几次是 804、1353 ms)。为什么偏小又不稳定,我没有查清。把它当作“哪个栈等得多”的相对排序用,不要当作精确的总时间。</p>'),
     ('用任务与区域标注业务', '<p><code>trace.NewTask</code> / <code>trace.WithRegion</code> 把你关心的阶段写进 trace,<code>go tool trace -d=parsed</code> 里能直接读到 Begin/End 的纳秒时间戳。三个各睡 10 ms 的步骤读出来是 12.03、12.03、12.01 ms,和之前量到的 <code>Sleep</code> 多睡约 2 ms 一致。</p>'),
     ('代价', '<p>一个 200 个 goroutine、每个分配 400 次的小程序,开 trace 后中位耗时从 0.041 s 到 0.050 s,约慢 22%,生成 0.9 MB,折合每秒约 18 MB。真实服务的开销取决于事件密度,我只测了这一个例子。</p>'),
     ('四种命令行 profile', '<p><code>-pprof=</code> 支持 net、sync、syscall、sched 四种。本文只实验了 sync 与 sched;net 与 syscall 没有试。网页界面(火焰图式的时间线)需要浏览器,这里没有使用。</p>')],
    steps,
    [ENV_G + '。程序分别用 runtime/trace 写出 trace 文件,再用 go tool trace -pprof=… 与 -d=parsed 读取;程序自己的排队计时在每个 goroutine 里用 time.Since(created) 记录;区域时长由 -d=parsed 里的 RegionBegin/RegionEnd 时间戳相减;开销对比各 5 次;读过的文档:go doc runtime/trace,go tool trace -h',
     '没有验证:网页界面(时间线/goroutine 分析)、-pprof=net 与 -pprof=syscall、sched profile 总量偏小的原因、trace 对真实服务的影响、飞行记录器(flight recorder)、Linux 上的结果'],
    '执行追踪')
